const fs = require('fs');
const path = require('path');

// Default values
const DEFAULT_PORT = 3000;
const DEFAULT_HTTPS_PORT = 3443;

// Get port from environment variables or use defaults
const PORT = process.env.PORT || DEFAULT_PORT;
const HTTPS_PORT = process.env.HTTPS_PORT || DEFAULT_HTTPS_PORT;

// Get TLS certificate paths from environment variables
const TLS_CERT_PATH = process.env.TLS_CERT_PATH;
const TLS_KEY_PATH = process.env.TLS_KEY_PATH;

// Function to check if TLS files exist and are readable
function getTlsOptions() {
  // If either certificate path is not set, return null
  if (!TLS_CERT_PATH || !TLS_KEY_PATH) {
    return null;
  }

  try {
    // Check if certificate file exists and is readable
    if (!fs.existsSync(TLS_CERT_PATH)) {
      console.warn(`TLS certificate file not found: ${TLS_CERT_PATH}`);
      return null;
    }

    // Check if key file exists and is readable
    if (!fs.existsSync(TLS_KEY_PATH)) {
      console.warn(`TLS key file not found: ${TLS_KEY_PATH}`);
      return null;
    }

    // Read the certificate and key files
    const certificate = fs.readFileSync(TLS_CERT_PATH);
    const privateKey = fs.readFileSync(TLS_KEY_PATH);

    return {
      cert: certificate,
      key: privateKey
    };
  } catch (error) {
    console.warn(`Error reading TLS files: ${error.message}`);
    return null;
  }
}

